from taf.rfrl.bts.devices.du.pm_counters import GenericPmCounter
from taf.rfrl.procedures.resources.python.counters.exceptions import ParameterNotConfigured
from taf.rfrl.procedures.resources.python.logger import log_input_and_output, log_result


class Counters(GenericPmCounter):
    @log_input_and_output
    def get_value_of_parameter(self, dist_name, parameter_name):
        """
        Returns value of a desired parameter, if parameter is not configured exception is raised

        :param dist_name: Distname of the parameter i.e. MRBTS-50172/MNL-1/MNLENT-1/PMMNL-1
        :type dist_name: str
        :param parameter_name: abbreviated name of the parameter i.e. eCpriMasterStatisticsInterval
        :type parameter_name: str

        :raises: ParameterNotConfigured when desired parameter is not configured
        :return: parameter value
        :rtype: str
        """
        try:
            parameter_value = self.get_pm_interval(dist_name=dist_name, abbr_group_name=parameter_name)
            log_result(
                "{0} parameter with distname: {1} is configured with value: {2}".format(
                    dist_name, parameter_name, parameter_value))
            return parameter_value
        except KeyError:
            raise ParameterNotConfigured(
                "Desired parameter {0} with distname {1} is not configured!".format(parameter_name, dist_name))
